}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

.thread-root-message p {
    margin: 4px 0 0;
    font-size: 0.9rem;
    color: #dbdee1;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #3f4147;
}

